msg.cameraSlug = slug;
msg.cameraName = SLUG_LABELS[slug] || displayName(slug);
msg.watchdogKey = 'watchdog_state_camera_' + slug;
return msg;

const SLUG_LABELS = {
    backGate: 'Back Gate',
    casaSpate: 'Casa Spate',
    frontHouse: 'Front House',
    gazonCurte: 'Gazon Curte',
    gradinaLunca: 'Gradina Lunca Cetatuii',
    smallGateEntrance: 'Small Gate Entrance',
    streetView: 'Street View Camera'
};

function displayName(slug) {
    if (SLUG_LABELS[slug]) return SLUG_LABELS[slug];
    return slug.replace(/_/g, ' ').replace(/([a-z])([A-Z])/g, '$1 $2')
        .replace(/\b\w/g, c => c.toUpperCase());
}

const parts = (msg.topic || '').split('/');
const slug = parts[2];
if (!slug) return null;

msg.cameraSlug = slug;
msg.cameraName = SLUG_LABELS[slug] || displayName(slug);
msg.watchdogKey = 'watchdog_state_camera_' + slug;
msg.offlineReason = 'timeout';
return msg;

const key = msg.watchdogKey;
if (!key) return null;
const prev = flow.get(key);
if (prev === 'online') return null;
flow.set(key, 'online');
return msg;

const key = msg.watchdogKey;
if (!key) return null;
const prev = flow.get(key);
if (prev === 'offline') return null;
flow.set(key, 'offline');
return msg;

msg.payload = {
    chatId: 991635368,
    type: 'message',
    content: `🟢 *Camera ONLINE*\n\n📷 ${msg.cameraName}\nTopic: ${msg.topic}`,
    parse_mode: 'Markdown'
};
return msg;

const reason = msg.offlineReason === 'reported'
    ? 'ICMP ping failed (camera not reachable on LAN).'
    : 'No online ping for 3 minutes. Check camera-ping-watchdog.service and camera power/network.';

msg.payload = {
    chatId: 991635368,
    type: 'message',
    content: `🔴 *Camera OFFLINE*\n\n📷 ${msg.cameraName}\n${reason}\nTopic: ${msg.topic}`,
    parse_mode: 'Markdown'
};
return msg;
